// Mind graph data, built once at build time.
//
// Two constellations feed the /mind star map:
//   - "portfolio": derived from info.projects + disciplines + the posts on disk.
//   - "repo": read from repo-graph.json, regenerated by scripts/gen-repo-graph.mjs
//     (fetches the GitHub contributions graph in CI). A committed snapshot keeps
//     local builds working without a token.
//
// Nothing here does layout: the star positions are settled client-side by a small
// force simulation in the Mind stage, so the same data animates into place.

import { info } from "../info";
import { disciplines } from "../disciplines";
import { architectures } from "../architecture";
import repoGraphSnapshot from "./repo-graph.json";
import { readPosts } from "../../utils/postFiles";

export type MindNodeType =
  | "discipline"
  | "project"
  | "tech"
  | "post"
  | "repo"
  | "org"
  | "language"
  | "category";

export interface MindNode {
  id: string;
  type: MindNodeType;
  label: string;
  color: string; // hex — the star's tint
  weight: number; // relative star size / gravity (1 = smallest)
  url?: string; // where clicking through goes (case study, demo, repo)
  links?: MindLink[]; // every place to read more: post, drawing, demo, public repo
  blurb?: string; // one line for the detail card
  meta?: string; // small dim label (tier, language, "12 repos", etc.)
  chips?: string[]; // small tags shown in the detail card (tech, languages, topics)
}

export interface MindLink {
  label: string;
  url: string;
}

export interface MindEdge {
  source: string;
  target: string;
}

export interface MindGraph {
  key: "portfolio" | "repo";
  title: string;
  subtitle: string;
  nodes: MindNode[];
  edges: MindEdge[];
}

// Each post's frontmatter, for its drawing and demo.
const postMeta = (url?: string) => {
  if (!url || !url.startsWith("/posts/")) return null;
  const slug = url.replace(/^\/posts\//, "").replace(/\/$/, "");
  const hit = readPosts().find((p) => p.url === `/posts/${slug}`);
  return hit ? (hit.frontmatter as { architecture?: string; demo?: string }) : null;
};
// Where a star leads on this site: its post, its architecture drawing, its
// demo, and an outside link when there is one.
function siteLinks(post?: string, link?: string): MindLink[] {
  const out: MindLink[] = [];
  if (post) out.push({ label: "Read the post", url: post });
  const fm = postMeta(post);
  const arch = fm?.architecture || (post ? architectures.find((a) => a.post === post)?.slug : undefined);
  if (arch) out.push({ label: "Open the drawing", url: `/architecture/${arch}` });
  if (fm?.demo) out.push({ label: "Try the demo", url: fm.demo });
  if (link && link !== post && !out.some((l) => l.url === link)) out.push({ label: /^https?:/.test(link) ? "Visit" : "View", url: link });
  return out;
}

// Which projects use which: a shared service is linked to every app that
// calls it. Read from the service inventory's call graph.
const PROJECT_LINKS: [string, string][] = [
  ["Denticon Sync", "Patient Dashboard"],
  ["Denticon Sync", "CDF Registry"],
  ["CDF Registry", "Patient Dashboard"],
  ["CDF Registry", "Treatment Estimator"],
  ["CDF Registry", "Capacity Planner"],
  ["PDF Renderer", "Patient Dashboard"],
  ["PDF Renderer", "Centralized Diagnostic Filter"],
  ["Centralized Diagnostic Filter", "Patient Dashboard"],
  ["Treatment Estimator", "Patient Dashboard"],
  ["Doc Coach, Consultation QA Pipeline", "Patient Dashboard"],
  ["Treatment Sequence", "Treatment Estimator"],
  ["Feature Requests Relay", "Launchpad"],
  ["Feature Requests Relay", "Patient Dashboard"],
  ["Feature Requests Relay", "Treatment Estimator"],
  ["Feature Requests Relay", "Capacity Planner"],
  ["Feature Requests Relay", "Hybridge Forms"],
  ["Feature Requests Relay", "Cowork Dashboard"],
  ["Feature Requests Relay", "Doctor Portal"],
  ["Hybridge Forms", "Hybridge Websites"],
  ["Marketing Data Connector", "Marketing Data Warehouse"],
];

const TECH_TINT = "#7FA8D8"; // cool starlight for technologies
const POST_TINT = "#22D3EE"; // cyan for writing / case studies
const NEUTRAL = "#93A4C4";

function slug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

// Distinctive tokens shared between two names — used to tie a project to the
// discipline that claims it (their labels differ slightly across data sources).
const STOP = new Set([
  "the", "a", "an", "and", "of", "for", "to", "with", "at", "on", "in",
  "ai", "qa", "rag", "pipeline", "platform", "system", "engine", "app",
]);
function tokens(s: string): Set<string> {
  return new Set(
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .split(" ")
      .filter((t) => t.length >= 3 && !STOP.has(t)),
  );
}
function related(a: string, b: string): boolean {
  const ta = tokens(a);
  const tb = tokens(b);
  let shared = 0;
  for (const t of ta) if (tb.has(t)) shared++;
  return shared >= 2 || [...ta].some((t) => t.length >= 5 && tb.has(t));
}

// Which discipline a project belongs to when its name doesn't match one, judged
// by what it's built with — so every project still anchors to a quadrant.
function techDisciplineSlug(tech: string[]): string {
  const t = tech.join(" ").toLowerCase();
  if (/pytorch|monai|lightning|ray|mlflow|sklearn|resnet|onnx|openvino|grpo|ppo|rlhf|qlora|llama/.test(t)) return "mle";
  if (/gemini|llm|rag|vertex|openai|embedding|firestore|document ai/.test(t)) return "aie";
  if (/next\.js|react|typescript|drizzle|auth\.js|tailwind|astro|node\.js|spring/.test(t)) return "sde";
  return "fde";
}

function buildPortfolio(): MindGraph {
  const nodes = new Map<string, MindNode>();
  const edges: MindEdge[] = [];
  const seenEdge = new Set<string>();

  const add = (n: MindNode) => {
    if (!n.id) return;
    if (!nodes.has(n.id)) nodes.set(n.id, n);
  };
  const link = (source: string, target: string) => {
    if (!source || !target || source === target) return;
    const k = `${source}\u0000${target}`;
    if (seenEdge.has(k)) return;
    seenEdge.add(k);
    edges.push({ source, target });
  };

  // Discipline anchor stars — the brightest points in the sky.
  for (const d of disciplines) {
    add({
      id: `disc:${d.slug}`,
      type: "discipline",
      label: d.acronym,
      color: d.accent,
      weight: 6,
      url: `/work/${d.slug}`,
      links: [{ label: "Open the work page", url: `/work/${d.slug}` }],
      blurb: d.tagline,
      meta: d.name,
    });
  }

  // Projects, with their technology webs. Every project anchors to at least one
  // discipline: by name when a discipline claims it, else by its tech stack.
  for (const p of info.projects as any[]) {
    const pid = `proj:${slug(p.title)}`;
    let discSlugs = disciplines
      .filter((d) => (d.projects || []).some((dp: any) => related(p.title, dp.name)))
      .map((d) => d.slug);
    if (discSlugs.length === 0) discSlugs = [techDisciplineSlug(p.tech || [])];
    const color = disciplines.find((d) => d.slug === discSlugs[0])?.accent ?? NEUTRAL;
    const blurb =
      p.details?.summary_short || p.details?.summary || p.description || "";
    add({
      id: pid,
      type: "project",
      label: p.title,
      color,
      weight: p.flagshipRank ? 4.4 : 3.4,
      url: p.post || p.link || undefined,
      links: siteLinks(p.post, p.link),
      blurb: blurb.slice(0, 220),
      meta: p.tier,
      chips: (p.tech || []).slice(0, 8),
    });
    for (const s of discSlugs) link(`disc:${s}`, pid);

    for (const tech of (p.tech || []) as string[]) {
      const tid = `tech:${slug(tech)}`;
      add({ id: tid, type: "tech", label: tech, color: TECH_TINT, weight: 1.5 });
      link(pid, tid);
    }

    if (p.post) {
      const postId = `post:${slug(p.post)}`;
      add({
        id: postId,
        type: "post",
        label: p.title,
        color: POST_TINT,
        weight: 1.8,
        url: p.post,
        links: siteLinks(p.post),
        blurb: "Case study",
        meta: "writing",
      });
      link(pid, postId);
    }
  }

  // Projects that use one another: shared services and the apps that call
  // them, from the service inventory (who calls whom, October 29, 2026).
  const titles = new Map((info.projects as any[]).map((p) => [p.title, `proj:${slug(p.title)}`]));
  for (const [a, b] of PROJECT_LINKS) {
    const ia = titles.get(a), ib = titles.get(b);
    if (ia && ib) link(ia, ib);
  }

  return {
    key: "portfolio",
    title: "Portfolio Graph",
    subtitle: "Projects, disciplines, and the tools they share",
    nodes: [...nodes.values()],
    edges,
  };
}

// Git Mind follows the portfolio's rules: four tech stacks are the anchors
// (like the disciplines), every repository hangs off the stacks it belongs to
// (like a project), and each language hangs off the repos written in it (like
// a technology). Organisations are left out.
const STACKS: Record<string, string> = {
  ai: "AI and LLMs",
  ml: "Machine learning",
  web: "Web and apps",
  data: "Backend and data",
};

// The stacks each repository belongs to, by what the repo is, not only by
// its languages. Repos not listed here (new ones the CI snapshot picks up)
// are sorted by the words in their name and description, then by language.
const REPO_STACKS: Record<string, string[]> = {
  "sampreethavvari.github.io": ["web"],
  "solstice-mvp": ["web"],
  "cbct-scan-validator": ["ml"],
  "treatment-estimator": ["web", "data"],
  "hybridge-consultation-qa": ["ai"],
  "hybridge-accounting-tools": ["data"],
  "voiceagents-demo": ["ai"],
  "hybridge-npc-coaching": ["ai"],
  "job-pilot": ["ai", "web"],
  "ledger-notes-verifier": ["data"],
  "hybridge-dashboard": ["web"],
  "hybridge-assessment": ["web", "ai"],
  "hybridge-enterprise-search": ["ai"],
  "jobpilot-demo": ["web"],
  "golden-hammer-sports": ["web"],
  previz: ["ai"],
  "magic-hour": ["ai"],
  "hybridge-marketing-warehouse": ["data"],
  "personal-diary": ["web"],
  "ai-systems-tours": ["web"],
  "hybridge-treatment-sequence": ["data"],
  "hybridge-cdf": ["web"],
  "hybridge-cowork-dashboard": ["web"],
  "hybridge-capacity-planner": ["web"],
  "hybridge-portal": ["web"],
  "hybridge-forms": ["web"],
  "social-media-automation": ["ai"],
  "hybridge-ui-lab": ["web"],
  "hybridge-launchpad": ["web"],
  "hybridge-website": ["web"],
  "hybridge-lab-website": ["web"],
  "tastemaker-api-py": ["data"],
  "tastemaker-app": ["web"],
  "bluetroop.com": ["web"],
  "kandjservices-website": ["web"],
  "llm-persuasion": ["ai"],
  "loan-default-risk-assessment": ["ml"],
  nlp: ["ml"],
  bigdata: ["data", "ml"],
  us2020electionanalysis: ["ai", "ml"],
  dl_resnet: ["ml"],
  resnetunder50: ["ml"],
  testasdata: ["ml"],
  datasciencebootcamp: ["ml"],
  hw2: ["data"],
  needforspeed: ["data"],
  rtes: ["data"],
};
const STACK_WORDS: [string, RegExp][] = [
  ["ai", /\b(llm|gpt|gemini|claude|rag|agents?|chat ?bot|voice|copilot|prompt|persuasion|coach)/i],
  ["ml", /\b(model|classifier|resnet|cnn|deep learning|mlops|training|dataset|prediction|nlp|vision|notebook)/i],
  ["web", /\b(website|site|app|dashboard|portal|frontend|ui|astro|next\.?js|react)\b/i],
  ["data", /\b(api|backend|service|warehouse|pipeline|etl|sql|database|sync|reconcil)/i],
];
const LANG_STACK: Record<string, string> = {
  python: "data", "jupyter notebook": "ml",
  typescript: "web", javascript: "web", astro: "web", html: "web", css: "web", vue: "web", svelte: "web",
  go: "data", java: "data", "c++": "data", c: "data", rust: "data", plpgsql: "data", sql: "data", shell: "data",
};
function stacksOf(name: string, description: string, primary: string): string[] {
  const known = REPO_STACKS[name.toLowerCase()];
  if (known) return known;
  const text = `${name.replace(/[-_]/g, " ")} ${description}`;
  const hit = STACK_WORDS.filter(([, re]) => re.test(text)).map(([k]) => k);
  if (hit.length) return hit.slice(0, 2);
  return [LANG_STACK[primary.toLowerCase()] || "data"];
}

function buildRepo(): MindGraph {
  const snap = repoGraphSnapshot as {
    nodes: { id: string; type: string; label: string; data?: any }[];
    edges: { source: string; target: string; rel: string }[];
  };
  const nodes: MindNode[] = [];
  const edges: MindEdge[] = [];
  const keep = new Set<string>();
  const usedStacks = new Set<string>();

  for (const n of snap.nodes || []) {
    if (n.type !== "repo") continue;
    const d = n.data || {};
    const langs: string[] = d.languages || [];
    const description: string = (d.description || "").trim();
    // Leave out what is not work: empty repos, class placeholders, the
    // profile readme repo.
    if (!langs.length && !description) continue;
    if (/created by GitHub Classroom/i.test(description)) continue;
    if ((d.owner || "").toLowerCase() === n.label.toLowerCase()) continue;
    keep.add(n.id);
    const primary = d.primary_language || langs[0] || "";
    const stars = d.stars ? `${d.stars} star${d.stars === 1 ? "" : "s"} · ` : "";
    nodes.push({
      id: n.id,
      type: "repo",
      label: n.label,
      color: NEUTRAL,
      weight: d.private ? 4.6 : 5.2,
      url: d.private ? undefined : d.url,
      links: d.private || !d.url ? [] : [{ label: "Open the repository", url: d.url }],
      blurb: d.private ? "" : description,
      meta: `${stars}${d.private ? "private" : "public"}`,
      chips: langs.slice(0, 8),
    });
    for (const st of stacksOf(n.label, description, primary)) {
      usedStacks.add(st);
      edges.push({ source: `cat:${st}`, target: n.id });
    }
  }

  // Languages, only the ones a kept repo is written in.
  const langNodes = new Map<string, MindNode>();
  for (const e of snap.edges || []) {
    if (e.rel !== "uses-language" || !keep.has(e.source)) continue;
    const ln = (snap.nodes || []).find((x) => x.id === e.target);
    if (!ln) continue;
    if (!langNodes.has(ln.id)) {
      langNodes.set(ln.id, { id: ln.id, type: "language", label: ln.label, color: TECH_TINT, weight: 2.2, meta: "language" });
    }
    edges.push({ source: e.source, target: ln.id });
  }
  nodes.push(...langNodes.values());

  for (const [key, label] of Object.entries(STACKS)) {
    if (!usedStacks.has(key)) continue;
    nodes.push({ id: `cat:${key}`, type: "category", label, color: NEUTRAL, weight: 6.5, meta: "tech stack" });
  }

  const repoCount = nodes.filter((n) => n.type === "repo").length;
  return {
    key: "repo",
    title: "Git Mind",
    subtitle: `${repoCount} repositories, grouped by the tech stacks they belong to`,
    nodes,
    edges,
  };
}

export const portfolioGraph: MindGraph = buildPortfolio();
export const repoGraph: MindGraph = buildRepo();
export const mindGraphs: MindGraph[] = [portfolioGraph, repoGraph];
